#include <stdio.h>
#include <stdlib.h>

long binom(int n, int k) {
    if (k == 0 || k == n) return 1;
    if (k > n / 2) k = n - k;
    long* memo = (long*) calloc((n + 1) * (k + 1), sizeof(long));
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= k; j++) {
            if (j == 0 || j == i) {
                memo[j * (n + 1) + i] = 1;
            } else {
                memo[j * (n + 1) + i] = memo[(j - 1) * (n + 1) + i - 1] + memo[j * (n + 1) + i - 1];
            }
        }
    }
    long result = memo[k * (n + 1) + n];
    free(memo);
    return result;
}

int main(int argc, char** argv) {
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }
    int n = strtol(argv[1], NULL, 10);
    int k = strtol(argv[2], NULL, 10);
    if (n < 0 || k < 0 || k > n) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (n == 0 && k == 0) {
        puts("BAD_INPUT");
        return 0;
    }
    printf("%lld\n", binom(n, k));
    return 0;
}
